use aztec::{
    keys::ecdh_shared_secret::compute_app_siloed_shared_secret,
    macros::notes::note,
    messages::delivery::handshake::AppSiloedHandshakeSecrets,
    protocol::{
        address::AztecAddress,
        constants::DOM_SEP__CONSTRAINED_MSG_SENDER_SECRET,
        hash::poseidon2_hash_with_separator,
        point::EmbeddedCurvePoint,
        traits::{Deserialize, Packable, Serialize, ToField},
    },
};

/// A record of a handshake established by the note's owner (the sender).
///
/// Stored in [`crate::HandshakeRegistry`]'s `handshakes` state. Holds the raw ECDH shared-secret point `S`. App
/// contracts never see `S` directly: they call the registry's private surface, which
/// silos `S` against the calling contract's address and hands back the app-siloed `Field`.
#[derive(Deserialize, Eq, Packable, Serialize)]
#[note]
pub struct HandshakeNote {
    /// The raw ECDH shared-secret point `S = eph_sk * recipient_address_point`. Only this module can read it for
    /// siloing, and it is never returned by an external function.
    secret: EmbeddedCurvePoint,
    /// A sender-only random secret, generated by the sender when the handshake is created. Folded into
    /// constrained-delivery nullifiers so only the sender can advance a sequence; the recipient never sees it, as it
    /// is stored only in the sender's note and never transmitted. It leaves the registry only via
    /// [`HandshakeNote::nullifier_secret_for`], never unsiloed.
    sender_secret: Field,
}

impl HandshakeNote {
    pub(crate) fn new(shared_secret: EmbeddedCurvePoint, sender_secret: Field) -> Self {
        Self { secret: shared_secret, sender_secret }
    }

    /// Returns the [app-siloed handshake secrets][AppSiloedHandshakeSecrets] for `caller`: the shared secret (via
    /// aztec-nr's canonical [`compute_app_siloed_shared_secret`]) and the sender-only secret folded into
    /// constrained-delivery nullifiers so only the sender can advance a sequence. Both are siloed to `caller`, so a
    /// different caller receives different values for the same note; the raw `S` and `sender_secret` never leave the
    /// registry. The recipient cannot derive the sender-only secret: `sender_secret` is random, known only to the
    /// sender, and never transmitted.
    pub(crate) fn app_siloed_secrets_for(self, caller: AztecAddress) -> AppSiloedHandshakeSecrets {
        AppSiloedHandshakeSecrets {
            shared: compute_app_siloed_shared_secret(self.secret, caller),
            sender_only: poseidon2_hash_with_separator(
                [self.sender_secret, caller.to_field()],
                DOM_SEP__CONSTRAINED_MSG_SENDER_SECRET,
            ),
        }
    }
}

